class Solution {
public:
    std::vector<std::vector<int>> minScore(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::tuple<int, int, int>> cells;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                cells.push_back({grid[r][c], r, c});
            }
        }
        std::sort(cells.begin(), cells.end());
        std::vector<int> row_max(m, 0), col_max(n, 0);
        std::vector<std::vector<int>> res(m, std::vector<int>(n, 0));
        for (const auto& [val, r, c] : cells) {
            int v = std::max(row_max[r], col_max[c]) + 1;
            res[r][c] = v;
            row_max[r] = v;
            col_max[c] = v;
        }
        return res;
    }
};

class Solution {
    public int[][] minScore(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] cells = new int[m * n][3];
        int idx = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                cells[idx++] = new int[]{grid[r][c], r, c};
            }
        }
        java.util.Arrays.sort(cells, (a, b) -> Integer.compare(a[0], b[0]));
        int[] rowMax = new int[m];
        int[] colMax = new int[n];
        int[][] res = new int[m][n];
        for (int[] cell : cells) {
            int r = cell[1], c = cell[2];
            int v = Math.max(rowMax[r], colMax[c]) + 1;
            res[r][c] = v;
            rowMax[r] = v;
            colMax[c] = v;
        }
        return res;
    }
}

var minScore = function(grid) {
    const m = grid.length, n = grid[0].length;
    const cells = [];
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            cells.push([grid[r][c], r, c]);
        }
    }
    cells.sort((a, b) => a[0] - b[0]);
    const rowMax = new Array(m).fill(0);
    const colMax = new Array(n).fill(0);
    const res = Array.from({ length: m }, () => new Array(n).fill(0));
    for (const [val, r, c] of cells) {
        const v = Math.max(rowMax[r], colMax[c]) + 1;
        res[r][c] = v;
        rowMax[r] = v;
        colMax[c] = v;
    }
    return res;
};
